// 2.2 Function node: демонстрация базовых элементов JS
// Используем: let/const, if/else, for, массив, объект

// 1. Получаем число из inject
const input = msg.payload;

// 2. Массив — список чисел
const numbers = [1, 2, 3, 4, 5];

// 3. Считаем сумму через цикл for
let sum = 0;
for (let i = 0; i < numbers.length; i++) {
    sum += numbers[i];
}

// 4. Условие if/else — проверяем чётность входного числа
let parity;
if (input % 2 === 0) {
    parity = "чётное";
} else {
    parity = "нечётное";
}

// 5. Формируем объект-результат
const result = {
    input: input,
    parity: parity,
    sum: sum,
    numbers: numbers
};

// 6. Возвращаем сообщение с результатом
msg.payload = result;
return msg;
